/**
 * PWA bootstrap — registers the generated service worker.
 *
 * The worker is generated by scripts/cache-bust.js and precaches the app shell,
 * all 28 animal cues and the PWA icons (~1.5 MB), so the game keeps working in
 * an offline classroom after the first visit.
 */
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker
      .register('sw.js')
      .catch((error) => {
        console.warn('[PWA] Service worker registration failed:', error);
      });
  }, { once: true });
}
